<?php
namespace App\Livewire\Tenant\Maintenance; use App\Livewire\Concerns\InteractsWithAuthenticatedUser; use App\Livewire\Concerns\InteractsWithRoleShells; use App\Models\MaintenanceRequest; use App\Models\MaintenanceRequestPhoto; use App\Models\OccupancyComplaint; use App\Models\User; use App\Support\WorkflowNotifier; use Illuminate\View\View; use Livewire\Component; use Livewire\WithFileUploads;
class Show extends Component {use InteractsWithAuthenticatedUser,InteractsWithRoleShells,WithFileUploads; public MaintenanceRequest $request; public ?string $reason=null; public mixed $photo=null; public function mount(MaintenanceRequest $request):void{abort_unless($request->tenant_id===$this->currentUserId(),404);$this->request=$request->load(['property','landlord','events','photos']);} public function confirmResolution():void{abort_unless($this->request->status==='resolved',422);$this->request->update(['status'=>'closed','tenant_confirmed_at'=>now(),'closed_at'=>now()]);$this->event('tenant_confirmed');app(WorkflowNotifier::class)->notify($this->request->landlord,'maintenance-closed:'.$this->request->id,'The tenant confirmed the maintenance issue is resolved.',$this->request->title,route('landlord.maintenance.show',$this->request),'maintenance','View request');$this->reload();} public function reportUnresolved():void{$this->validate(['reason'=>['required','string','min:10','max:1000'],'photo'=>['nullable','image','mimes:jpg,jpeg,png,webp','max:5120']]);abort_unless($this->request->status==='resolved',422);$this->request->update(['status'=>'in_progress']);$this->event('tenant_unresolved',$this->reason);if($this->photo){$path=$this->photo->store('maintenance-requests/'.$this->request->id.'/tenant','local');MaintenanceRequestPhoto::create(['maintenance_request_id'=>$this->request->id,'uploaded_by_id'=>$this->currentUserId(),'source'=>'tenant','file_path'=>$path,'original_name'=>$this->photo->getClientOriginalName(),'file_size'=>$this->photo->getSize()]);}app(WorkflowNotifier::class)->notify($this->request->landlord,'maintenance-unresolved:'.$this->request->id,'The tenant says the maintenance issue is still unresolved.',$this->request->title,route('landlord.maintenance.show',$this->request),'maintenance','View request');$this->reset('reason','photo');$this->reload();} public function escalate():void{abort_unless(in_array($this->request->status,['in_progress','resolved'],true),422);$complaint=OccupancyComplaint::query()->firstOrCreate(['maintenance_request_id'=>$this->request->id],['occupancy_id'=>$this->request->occupancy_id,'tenant_id'=>$this->request->tenant_id,'category'=>'maintenance','description'=>'Maintenance escalation: '.$this->request->title.'. '.$this->request->description,'status'=>'open']);if(!$this->request->escalated_at){$this->request->update(['escalated_at'=>now()]);$this->event('escalated');User::role(['admin','staff'])->get()->each(fn(User $u)=>app(WorkflowNotifier::class)->notify($u,'maintenance-escalated:'.$this->request->id,'Maintenance request escalated to VerifyHomes.',$this->request->title,route('admin.occupancy.index'),'maintenance','Review issue'));}$this->reload();} private function event(string $type,?string $note=null):void{$this->request->events()->create(['actor_id'=>$this->currentUserId(),'event_type'=>$type,'note'=>$note]);} private function reload():void{$this->request->refresh()->load(['property','landlord','events','photos']);} public function render():View{return view('livewire.tenant.maintenance.show')->layout('layouts.dashboard-shell',$this->tenantShell('Maintenance Request'));}}
